fn put64(out:&mut [u8],p:usize,x:i64){out[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle] pub unsafe extern "C" fn edn_lattice_synthesis(raw:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if raw.is_null()||n<2||n>34{return -1}let v=unsafe{std::slice::from_raw_parts(raw,n)};let order=v[0];let mut f=v[1];if !(1..=16).contains(&order)||!(-65536..=65535).contains(&f)||n!=2+2*order as usize{return -1}let q=order as usize;let mut b=[0i64;16];let mut k=[0i64;16];for i in 0..q{b[i]=v[2+i];k[i]=v[2+q+i];if !(-1024..=1023).contains(&b[i])||!(-1024..=1023).contains(&k[i]){return -1}}let bytes=8*(q+1);if out.is_null()||cap<bytes{return -2}f-=b[q-1]*k[q-1];for z in (1..q).rev(){let i=z-1;f-=b[i]*k[i];b[i+1]=b[i]+((k[i]*(f>>16))>>16)}b[0]=f>>16;let output=unsafe{std::slice::from_raw_parts_mut(out,bytes)};put64(output,0,f);for i in 0..q{put64(output,8*(i+1),b[i])}bytes as i64}
